// The token source (FR-008, research.md R-01, data-model.md § Token): every token of spec Appendix A as a record, in
// the order of its tables. Each record's use (Appendix A's "Use" column) is the comment beside it, not data
// (PLAN-TESTABILITY-1-003 (a)). A derived token (FR-002) writes its source as var(--ocelle-<name>) and lists it in
// `ref`; a foreground colour carries its contrast kind and intended grounds (A.8: 149 required pairs per theme).
// `source` is the records with the overrides of overrides.ts applied; the generator, the build and the gates read it.
// No type assertion wraps the records or the ground lists (`as const`, `satisfies`): Stryker does not mutate inside
// one, so the values would go untested (op 004). `tokenRecords` keeps the names literal and checks each record instead.
import { applyOverrides } from "./generate.ts";
import type { TokenRecord } from "./generate.ts";
import { overrides } from "./overrides.ts";

/** A.8's main grounds: the grounds of #5's "Use" column on which content sits. */
const main = [
  "color-canvas",
  "color-sheet",
  "color-pane",
  "color-panel",
  "color-inspector",
  "color-rail",
  "color-inset",
  "color-accent-low",
  "color-hover-bg",
];
/** The five state grounds. */
const stateGrounds = ["color-danger-bg", "color-warning-bg", "color-success-bg", "color-info-bg", "color-neutral-bg"];
/** The chrome grounds. */
const chrome = ["color-chrome", "color-chrome-hover"];

/** The records as given; N keeps each name literal, so TokenName (index.ts) is their union without `as const`. */
function tokenRecords<const N extends string>(list: readonly (TokenRecord & { readonly name: N })[]): readonly (TokenRecord & { readonly name: N })[] {
  return list;
}

export const records = tokenRecords([
  // A.1 Colour (theme-dependent)
  { name: "color-canvas", group: "colour", value: { light: "#F1EEE8", dark: "#15130F" } }, // bone, the page ground
  { name: "color-sheet", group: "colour", value: { light: "#FBFAF7", dark: "#211E18" } }, // facts sheet, cards, inputs
  { name: "color-pane", group: "colour", value: { light: "#FFFFFF", dark: "#1C1A15" } }, // detail reading pane
  { name: "color-panel", group: "colour", value: { light: "#F1EEE8", dark: "#15130F" } }, // list and inspector panels
  { name: "color-inspector", group: "colour", value: { light: "#F1EEE8", dark: "#15130F" } }, // right inspector, ruled off
  { name: "color-rail", group: "colour", value: { light: "#E9E5DD", dark: "#1C1A15" } }, // context sidebar
  { name: "color-inset", group: "colour", value: { light: "#E2DDD3", dark: "#302B23" } }, // wells, digest backgrounds
  { name: "color-ink", group: "colour", value: { light: "#15130F", dark: "#EDE9E1" }, contrast: { kind: "text", grounds: main } }, // body text
  // secondary headings
  { name: "color-ink-soft", group: "colour", value: { light: "#3F3A33", dark: "#CFC9BE" }, contrast: { kind: "text", grounds: main } },
  // muted text
  { name: "color-ink-muted", group: "colour", value: { light: "#5E584F", dark: "#A39D92" }, contrast: { kind: "text", grounds: main } },
  { name: "color-rule", group: "colour", value: { light: "#D9D3C7", dark: "#3A342B" } }, // decorative, never a control boundary
  { name: "color-rule-strong", group: "colour", value: { light: "#B9B1A2", dark: "#4D463A" } }, // decorative
  // inputs, buttons, chips; on accent-low, inset, hover-bg and the state grounds controls use color-accent-strong (#5 rule 1)
  {
    name: "color-control-border",
    group: "colour",
    value: { light: "#8A8276", dark: "#7A7264" },
    contrast: { kind: "non-text", grounds: ["color-canvas", "color-sheet", "color-pane", "color-panel", "color-inspector", "color-rail"] },
  },
  { name: "color-chrome", group: "colour", value: { light: "#15130F", dark: "#0D0C0A" } }, // top bar, icon rail, personal rail
  { name: "color-chrome-ink", group: "colour", value: { light: "#EDE9E1", dark: "#EDE9E1" }, contrast: { kind: "text", grounds: chrome } }, // on chrome
  { name: "color-chrome-muted", group: "colour", value: { light: "#A39D92", dark: "#A39D92" }, contrast: { kind: "text", grounds: chrome } }, // on chrome
  // on chrome; light #211D18 replaces #5's #2A261F so the focus ring meets 3:1 on it (research.md R-04, SPEC-2-01)
  { name: "color-chrome-hover", group: "colour", value: { light: "#211D18", dark: "#24211B" } },
  { name: "color-accent", group: "colour", value: { light: "#C68A1E", dark: "#C68A1E" } }, // ochre fill
  // black on the ochre fill
  { name: "color-on-accent", group: "colour", value: { light: "#15130F", dark: "#15130F" }, contrast: { kind: "text", grounds: ["color-accent"] } },
  { name: "color-accent-low", group: "colour", value: { light: "#F1E1C0", dark: "#3A2B10" } }, // selected rows, current nav
  // current bar, focus ring; the border of a control on accent-low, inset, hover-bg and the state grounds (#5 rule 1, extended)
  {
    name: "color-accent-strong",
    group: "colour",
    value: { light: "#8F5E0F", dark: "#E0A23A" },
    contrast: { kind: "non-text", grounds: ["color-accent-low", "color-inset", "color-hover-bg", ...stateGrounds] },
  },
  // focus ring
  {
    name: "color-focus",
    group: "colour",
    value: { light: "var(--ocelle-color-accent-strong)", dark: "var(--ocelle-color-accent-strong)" },
    ref: { light: ["color-accent-strong"], dark: ["color-accent-strong"] },
    contrast: { kind: "non-text", grounds: [...main, ...chrome, ...stateGrounds] },
  },
  // current bar
  {
    name: "color-current",
    group: "colour",
    value: { light: "var(--ocelle-color-accent-strong)", dark: "var(--ocelle-color-accent-strong)" },
    ref: { light: ["color-accent-strong"], dark: ["color-accent-strong"] },
    contrast: { kind: "non-text", grounds: [...chrome, "color-rail", "color-accent-low"] },
  },
  // links
  { name: "color-link", group: "colour", value: { light: "#84560D", dark: "#E0A23A" }, contrast: { kind: "text", grounds: [...main, ...stateGrounds] } },
  // links on hover
  { name: "color-link-hover", group: "colour", value: { light: "#15130F", dark: "#F7F4EE" }, contrast: { kind: "text", grounds: main } },
  { name: "color-hover-bg", group: "colour", value: { light: "#E2DDD3", dark: "#2A261F" } }, // hovered rows and controls
  // disabled text; exempt from the threshold (WCAG 1.4.3, FR-017)
  {
    name: "color-disabled-ink",
    group: "colour",
    value: { light: "#6F685D", dark: "#8C8579" },
    contrast: { kind: "text", grounds: [...main, "color-disabled-bg"], exempt: true },
  },
  { name: "color-disabled-bg", group: "colour", value: { light: "#E6E1D8", dark: "#2A261F" } }, // disabled controls
  { name: "color-overlay", group: "colour", value: { light: "rgb(21 19 15 / 0.5)", dark: "rgb(0 0 0 / 0.65)" } }, // dialog backdrop
  // danger state
  { name: "color-danger", group: "colour", value: { light: "#A8322C", dark: "#E97373" }, contrast: { kind: "text", grounds: [...main, "color-danger-bg"] } },
  { name: "color-danger-bg", group: "colour", value: { light: "#F6E2E0", dark: "#2E1616" } }, // danger ground
  // warning state
  { name: "color-warning", group: "colour", value: { light: "#7A5205", dark: "#E0A23A" }, contrast: { kind: "text", grounds: [...main, "color-warning-bg"] } },
  { name: "color-warning-bg", group: "colour", value: { light: "#F4E6C8", dark: "#2E2410" } }, // warning ground
  // success state
  { name: "color-success", group: "colour", value: { light: "#2F6B3A", dark: "#8FCB8F" }, contrast: { kind: "text", grounds: [...main, "color-success-bg"] } },
  { name: "color-success-bg", group: "colour", value: { light: "#E4EFE3", dark: "#15241A" } }, // success ground
  // info state
  { name: "color-info", group: "colour", value: { light: "#2C5E86", dark: "#A9C7E8" }, contrast: { kind: "text", grounds: [...main, "color-info-bg"] } },
  { name: "color-info-bg", group: "colour", value: { light: "#E6EDF3", dark: "#14202E" } }, // info ground
  // neutral state
  { name: "color-neutral", group: "colour", value: { light: "#5E584F", dark: "#A39D92" }, contrast: { kind: "text", grounds: [...main, "color-neutral-bg"] } },
  { name: "color-neutral-bg", group: "colour", value: { light: "#E6E1D8", dark: "#2A261F" } }, // neutral ground
  // not a colour: the theme's color-scheme keyword, applied by the base styles (#6) (PLAN-A11Y-SECURITY-1-004)
  { name: "color-scheme", group: "colour", value: { light: "light", dark: "dark" } },

  // A.2 Type (theme-independent)
  { name: "font-sans", group: "type", value: '"Schibsted Grotesk", "Helvetica Neue", Arial, system-ui, sans-serif' }, // all text
  { name: "font-display", group: "type", value: "var(--ocelle-font-sans)", ref: ["font-sans"] }, // display text
  { name: "figures", group: "type", value: "tabular-nums" }, // ids, digests, values
  { name: "font-size-xs", group: "type", value: "0.75rem" },
  { name: "font-size-sm", group: "type", value: "0.875rem" },
  { name: "font-size-md", group: "type", value: "1rem" },
  { name: "font-size-fact", group: "type", value: "1.0625rem" }, // facts sheet values
  { name: "font-size-subhead", group: "type", value: "1.125rem" }, // prose h2, 18 px (003)
  { name: "font-size-lg", group: "type", value: "1.25rem" },
  { name: "font-size-xl", group: "type", value: "1.5rem" },
  { name: "font-size-2xl", group: "type", value: "1.875rem" },
  { name: "line-height-tight", group: "type", value: "1.15" },
  { name: "line-height-normal", group: "type", value: "1.45" },
  { name: "line-height-relaxed", group: "type", value: "1.55" },
  { name: "line-height-compact", group: "type", value: "1.5" },
  { name: "line-height-prose", group: "type", value: "1.65" }, // prose running text (003)
  { name: "font-weight-regular", group: "type", value: "400" },
  { name: "font-weight-medium", group: "type", value: "500" },
  { name: "font-weight-strong", group: "type", value: "600" },
  { name: "font-weight-display", group: "type", value: "800" },
  { name: "tracking-display", group: "type", value: "-0.03em" }, // display letter spacing

  // A.3 Space, shape, size (theme-independent)
  { name: "space-1", group: "space", value: "0.25rem" },
  { name: "space-2", group: "space", value: "0.5rem" },
  { name: "space-3", group: "space", value: "0.75rem" },
  { name: "space-4", group: "space", value: "1rem" },
  { name: "space-5", group: "space", value: "1.25rem" },
  { name: "space-6", group: "space", value: "1.5rem" },
  { name: "space-7", group: "space", value: "2rem" },
  { name: "space-8", group: "space", value: "2.5rem" },
  { name: "space-9", group: "space", value: "3rem" },
  { name: "space-10", group: "space", value: "4rem" },
  { name: "gutter", group: "space", value: "var(--ocelle-space-4)", ref: ["space-4"] }, // page and dialog gutter
  { name: "radius-1", group: "shape", value: "2px" }, // small marks: dots, focus corners
  { name: "radius-2", group: "shape", value: "4px" }, // the one general radius
  { name: "radius-row", group: "shape", value: "6px" }, // rows and cards
  { name: "radius-shell", group: "shape", value: "10px" }, // the outer app shell only
  { name: "radius-pill", group: "shape", value: "999px" }, // state pills only
  { name: "border-width", group: "shape", value: "1px" },
  { name: "focus-width", group: "shape", value: "3px" }, // focus ring width
  { name: "focus-offset", group: "shape", value: "2px" }, // focus ring offset
  { name: "bar-width", group: "shape", value: "3px" }, // current bar width
  { name: "ring-step", group: "shape", value: "1.5px" },
  { name: "target-min", group: "size", value: "2.75rem" }, // 44px minimum target (spec-kitty-design#532)
  { name: "icon-size", group: "size", value: "1.25rem" },
  { name: "size-dot", group: "size", value: "0.45rem" },
  { name: "size-step", group: "size", value: "1.4rem" },
  { name: "size-avatar", group: "size", value: "1.6rem" },
  { name: "size-rail-item", group: "size", value: "2.5rem" },
  { name: "size-visually-hidden", group: "size", value: "1px" },

  // A.4 Shell and measure (theme-independent)
  { name: "shell-topbar-height", group: "shell", value: "3.25rem" },
  { name: "shell-rail-width", group: "shell", value: "3.25rem" },
  { name: "shell-sidebar-width", group: "shell", value: "20rem" },
  { name: "shell-inspector-width", group: "shell", value: "19rem" }, // replaces spec-kitty-design#505's 260px
  { name: "shell-main-max", group: "shell", value: "48rem" },
  { name: "shell-collapse-inspector", group: "shell", value: "75rem" },
  { name: "shell-collapse-sidebar", group: "shell", value: "45rem" },
  { name: "shell-height", group: "shell", value: "100dvh" },
  { name: "footer-h", group: "shell", value: "4.5rem" },
  { name: "measure-sheet", group: "shell", value: "var(--ocelle-shell-main-max)", ref: ["shell-main-max"] },
  { name: "measure-sentence", group: "shell", value: "var(--ocelle-shell-main-max)", ref: ["shell-main-max"] },
  { name: "measure-page", group: "shell", value: "100%" },
  { name: "measure-reading", group: "shell", value: "68ch" }, // prose paragraph measure (003)
  { name: "measure-cell", group: "shell", value: "12ch" }, // prose table cell floor (003)
  // the inline size of the nearest query container: caps a prose caption at its table's visible width (003)
  { name: "measure-container", group: "shell", value: "100cqi" },
  // the viewport's inline size minus two gutters (unit from the console prototype, research.md R-05)
  { name: "dialog-max-inline", group: "shell", value: "calc(100vw - 2 * var(--ocelle-gutter))", ref: ["gutter"] },
  // the viewport's block size minus two gutters (unit from the console prototype, research.md R-05)
  { name: "dialog-max-block", group: "shell", value: "calc(100dvh - 2 * var(--ocelle-gutter))", ref: ["gutter"] },
  // decision bar
  { name: "bar-block-narrow", group: "shell", value: "calc(2 * var(--ocelle-target-min) + 3 * var(--ocelle-space-2))", ref: ["target-min", "space-2"] },

  // A.5 Elevation (theme-dependent) and motion (theme-independent); light shadows and ring widths from the console
  // prototype (research.md R-05)
  {
    name: "elevation-sheet",
    group: "elevation",
    value: { light: "0 0 0 1px var(--ocelle-color-rule)", dark: "0 0 0 1px var(--ocelle-color-rule)" },
    ref: { light: ["color-rule"], dark: ["color-rule"] },
  },
  {
    name: "elevation-raised",
    group: "elevation",
    value: { light: "0 2px 4px rgb(21 19 15 / 0.10), 0 12px 32px rgb(21 19 15 / 0.16)", dark: "0 0 0 1px var(--ocelle-color-rule-strong)" },
    ref: { light: [], dark: ["color-rule-strong"] },
  },
  {
    name: "elevation-row",
    group: "elevation",
    value: { light: "0 0 0 1px var(--ocelle-color-control-border), 0 2px 8px rgb(21 19 15 / 0.08)", dark: "0 0 0 1px var(--ocelle-color-control-border)" },
    ref: { light: ["color-control-border"], dark: ["color-control-border"] },
  },
  {
    name: "elevation-seg",
    group: "elevation",
    value: { light: "0 0 0 1px var(--ocelle-color-control-border), 0 1px 2px rgb(21 19 15 / 0.08)", dark: "0 0 0 1px var(--ocelle-color-control-border)" },
    ref: { light: ["color-control-border"], dark: ["color-control-border"] },
  },
  { name: "elevation-bar", group: "elevation", value: { light: "0 -6px 16px rgb(21 19 15 / 0.05)", dark: "none" } }, // bottom bars
  { name: "motion-fast", group: "motion", value: "120ms" }, // 0ms under reduced motion
  { name: "motion-base", group: "motion", value: "200ms" }, // 0ms under reduced motion
  { name: "easing-standard", group: "motion", value: "cubic-bezier(0.22, 1, 0.36, 1)" },
]);

export const source: readonly TokenRecord[] = applyOverrides(records, overrides);

packages/tokens/test/source-table.test.t.source:
import { describe, expect, it } from "vitest";
import { css, json } from "../src/generate.ts";
import { source } from "../src/source.ts";
import { excludedNames, expectedTokens, inTheme, themedGroups } from "./expected.ts";
import type { ExpectedToken } from "./expected.ts";
import { blocks, fontFaceOutline, fourBlocks } from "./stylesheet.ts";

// The generator run on the real token source, compared token by token with spec Appendix A as transcribed in
// expected.ts (data-model.md § Expected tables; PLAN-FRESH-2-002, R-03 *Mutation path*): the stylesheet's declaration
// per theme (for colours the token stream, hex compared case-insensitively; for the others the exact text, derived
// tokens in their reference form, FR-002) and the JSON export's resolved values (FR-008). This test, not the browser
// suites, is what kills the value mutants of source.ts.
const full = (name: string): string => `--ocelle-${name}`;
const sheet = blocks(css(source));
const exported = json(source);

/** An expected ref in the JSON's full-name form, in the same shape. */
function fullRef(ref: ExpectedToken["ref"]): readonly string[] | { light: string[]; dark: string[] } | undefined {
  if (ref === undefined) return undefined;
  if ("light" in ref) return { light: ref.light.map(full), dark: ref.dark.map(full) };
  return ref.map(full);
}

/** A value as compared: colours case-insensitively, everything else exactly. */
function comparable(token: ExpectedToken, value: string | undefined): string | undefined {
  return token.compare === "colour" ? value?.toLowerCase() : value;
}

describe("the stylesheet from the real source", () => {
  it("has the @font-face of research.md R-06, then the four blocks of R-02, in order", () => {
    expect(sheet.outline).toEqual([fontFaceOutline, ...fourBlocks]);
  });

  it("declares exactly the tokens of Appendix A on :root, and none of A.6", () => {
    expect([...sheet.root.keys()].sort()).toEqual(expectedTokens.map((token) => full(token.name)).sort());
    expect(excludedNames.map(full).filter((name) => sheet.root.has(name) || sheet.darkSystem.has(name))).toEqual([]);
  });

  it("declares each token's light value (or its one value) in the unconditioned :root block", () => {
    const declared = Object.fromEntries(expectedTokens.map((token) => [token.name, comparable(token, sheet.root.get(full(token.name)))]));
    const expected = Object.fromEntries(expectedTokens.map((token) => [token.name, comparable(token, inTheme(token.declared, "light"))]));
    expect(declared).toEqual(expected);
  });

  it("declares each theme-dependent token's dark value under both dark selectors, where it differs from light", () => {
    const themed = expectedTokens.filter((token) => themedGroups.includes(token.group));
    const dark = (map: ReadonlyMap<string, string>): Record<string, string | undefined> =>
      Object.fromEntries(themed.map((token) => [token.name, comparable(token, map.get(full(token.name)) ?? sheet.root.get(full(token.name)))]));
    const expected = Object.fromEntries(themed.map((token) => [token.name, comparable(token, inTheme(token.declared, "dark"))]));
    expect(dark(sheet.darkSystem)).toEqual(expected);
    expect(dark(sheet.darkAttribute)).toEqual(expected);
    expect([...sheet.darkSystem.entries()]).toEqual([...sheet.darkAttribute.entries()]);
  });

  it("declares no theme-independent token under the dark selectors", () => {
    const independent = expectedTokens.filter((token) => !themedGroups.includes(token.group)).map((token) => full(token.name));
    expect(independent.filter((name) => sheet.darkSystem.has(name) || sheet.darkAttribute.has(name))).toEqual([]);
    expect(independent.length).toBeGreaterThan(0);
  });

  it("sets exactly motion-fast and motion-base to 0ms under reduced motion (FR-007)", () => {
    expect([...sheet.reducedMotion.entries()]).toEqual([
      ["--ocelle-motion-fast", "0ms"],
      ["--ocelle-motion-base", "0ms"],
    ]);
  });
});

describe("the JSON export from the real source", () => {
  it("has version 1 and exactly the tokens of Appendix A, none of A.6", () => {
    expect(exported.version).toBe(1);
    expect(exported.tokens.map((token) => token.name).sort()).toEqual(expectedTokens.map((token) => full(token.name)).sort());
    expect(exported.tokens.filter((token) => excludedNames.map(full).includes(token.name))).toEqual([]);
  });

  it("gives each token its group, its resolved value per theme (or its one value) and its references", () => {
    const byName = new Map(exported.tokens.map((token) => [token.name, token]));
    const actual = Object.fromEntries(
      expectedTokens.map((token) => {
        const entry = byName.get(full(token.name));
        if (entry === undefined) return [token.name, undefined];
        const values = "value" in entry ? { value: entry.value } : { light: comparable(token, entry.light), dark: comparable(token, entry.dark) };
        return [token.name, { group: entry.group, ...values, ref: entry.ref }];
      }),
    );
    const expected = Object.fromEntries(
      expectedTokens.map((token) => {
        const values =
          typeof token.resolved === "string"
            ? { value: token.resolved }
            : { light: comparable(token, token.resolved.light), dark: comparable(token, token.resolved.dark) };
        return [token.name, { group: token.group, ...values, ref: fullRef(token.ref) }];
      }),
    );
    expect(actual).toEqual(expected);
  });
});

packages/tokens/test/validate.test.ts.source:
import { describe, expect, it } from "vitest";
import { applyOverrides, validateSource } from "../src/generate.ts";
import type { TokenRecord } from "../src/generate.ts";
import { source } from "../src/source.ts";
import { fixture, withAdded, withRecord } from "./fixture.ts";

// validateSource() (data-model.md § Token, *Validation*): each rule fails with one message naming the token and the
// rule, all of them in one error, "invalid token source: <problem>; <problem>". The build, the gates and this test use
// it; a gate exits 2 on it.
const ink = (value: TokenRecord["value"], rest: Partial<TokenRecord> = {}): TokenRecord => ({ name: "color-ink", group: "colour", value, ...rest });
const focus = (light: string, dark: string, ref: { light: string[]; dark: string[] }): TokenRecord => ({
  name: "color-focus",
  group: "colour",
  value: { light, dark },
  ref,
});

describe("validateSource() accepts", () => {
  it("the fixture source", () => {
    expect(() => {
      validateSource(fixture);
    }).not.toThrow();
  });

  it("the real source", () => {
    expect(() => {
      validateSource(source);
    }).not.toThrow();
  });

  it("exempt on color-disabled-ink", () => {
    const disabled: TokenRecord = {
      name: "color-disabled-ink",
      group: "colour",
      value: { light: "#AAAAAA", dark: "#555555" },
      contrast: { kind: "text", grounds: ["color-ground"], exempt: true },
    };
    expect(() => {
      validateSource(withAdded(disabled));
    }).not.toThrow();
  });
});

const cases: readonly { readonly rule: string; readonly records: readonly TokenRecord[]; readonly problems: readonly string[] }[] = [
  {
    rule: "for a name that is not lower-case words joined by hyphens",
    records: withAdded({ name: "Color_A", group: "colour", value: { light: "#000000", dark: "#000000" } }),
    problems: ["token Color_A: name is not lower-case words joined by hyphens"],
  },
  {
    rule: "for a duplicate name",
    records: withAdded(ink({ light: "#111111", dark: "#EEEEEE" })),
    problems: ["token color-ink: duplicate name"],
  },
  {
    rule: "for a ref naming an unknown token",
    records: withRecord("gutter", { name: "gutter", group: "space", value: "var(--ocelle-space-9)", ref: ["space-9"] }),
    problems: ["token gutter: ref names an unknown token space-9"],
  },
  {
    rule: "for a ground naming an unknown token",
    records: withRecord("color-ink", ink({ light: "#111111", dark: "#EEEEEE" }, { contrast: { kind: "text", grounds: ["color-zz"] } })),
    problems: ["token color-ink: ground names an unknown token color-zz"],
  },
  {
    rule: "for a ref that lacks a reference of the value",
    records: withRecord("gutter", { name: "gutter", group: "space", value: "var(--ocelle-space-4)", ref: [] }),
    problems: ["token gutter: ref [] is not the set of references in the value [space-4]"],
  },
  {
    rule: "for a derived token without ref",
    records: withRecord("gutter", { name: "gutter", group: "space", value: "var(--ocelle-space-4)" }),
    problems: ["token gutter: ref [] is not the set of references in the value [space-4]"],
  },
  {
    rule: "for a ref that names a token the value does not reference",
    records: withRecord("gutter", { name: "gutter", group: "space", value: "var(--ocelle-space-4)", ref: ["space-4", "dialog-max"] }),
    problems: ["token gutter: ref [space-4, dialog-max] is not the set of references in the value [space-4]"],
  },
  {
    rule: "for a ref that does not match the value of the same theme",
    records: withRecord("elevation-raised", {
        name: "elevation-raised",
        group: "elevation",
        value: { light: "0 2px 4px rgb(0 0 0 / 0.1)", dark: "0 0 0 1px var(--ocelle-color-ink)" },
        ref: { light: ["color-ink"], dark: [] },
      }),
    problems: ["token elevation-raised: light ref [color-ink] is not the set of references in the light value []", "token elevation-raised: dark ref [] is not the set of references in the dark value [color-ink]"],
  },
  {
    rule: "for a ref that names a reference twice",
    records: withRecord("gutter", { name: "gutter", group: "space", value: "var(--ocelle-space-4)", ref: ["space-4", "space-4"] }),
    problems: ["token gutter: ref [space-4, space-4] is not the set of references in the value [space-4]"],
  },
  {
    rule: "for a ref that lacks one of several references of the value, naming them all",
    records: withAdded({ name: "bar", group: "shell", value: "calc(var(--ocelle-gutter) + var(--ocelle-space-4))", ref: ["gutter"] }),
    problems: ["token bar: ref [gutter] is not the set of references in the value [gutter, space-4]"],
  },
  {
    rule: "for a per-theme ref naming an unknown token, in either theme",
    records: withRecord("elevation-raised", {
        name: "elevation-raised",
        group: "elevation",
        value: { light: "0 2px 4px var(--ocelle-color-yy)", dark: "0 0 0 1px var(--ocelle-color-zz)" },
        ref: { light: ["color-yy"], dark: ["color-zz"] },
      }),
    problems: ["token elevation-raised: ref names an unknown token color-yy", "token elevation-raised: ref names an unknown token color-zz"],
  },
  {
    rule: "for a ref per theme on a value that is not, and the reverse",
    records: withRecord("gutter", { name: "gutter", group: "space", value: "var(--ocelle-space-4)", ref: { light: ["space-4"], dark: ["space-4"] } }).map((record) =>
        record.name === "elevation-raised" ? { ...record, ref: ["color-ink"] } : record,
      ),
    problems: ["token gutter: ref is per theme but the value is not", "token elevation-raised: value is per theme but the ref is not"],
  },
  {
    rule: "for a reference cycle",
    records: withAdded(
        { name: "loop-a", group: "space", value: "var(--ocelle-loop-b)", ref: ["loop-b"] },
        { name: "loop-b", group: "space", value: "calc(2 * var(--ocelle-loop-a))", ref: ["loop-a"] },
        { name: "loop-c", group: "space", value: "var(--ocelle-loop-c)", ref: ["loop-c"] },
      ),
    problems: ["token loop-a: reference cycle loop-a -> loop-b -> loop-a", "token loop-b: reference cycle loop-b -> loop-a -> loop-b", "token loop-c: reference cycle loop-c -> loop-c"],
  },
  {
    rule: "for a cycle that does not pass through the token that reaches it, only on the tokens on it",
    records: withAdded(
        { name: "lead-1", group: "space", value: "var(--ocelle-loop-a)", ref: ["loop-a"] },
        { name: "loop-a", group: "space", value: "var(--ocelle-loop-b)", ref: ["loop-b"] },
        { name: "loop-b", group: "space", value: "var(--ocelle-loop-a)", ref: ["loop-a"] },
      ),
    problems: ["token loop-a: reference cycle loop-a -> loop-b -> loop-a", "token loop-b: reference cycle loop-b -> loop-a -> loop-b"],
  },
  {
    rule: "for a cycle reached through a later reference, after one that ends",
    records: withAdded(
        { name: "loop-a", group: "space", value: "calc(var(--ocelle-space-4) + var(--ocelle-loop-b))", ref: ["space-4", "loop-b"] },
        { name: "loop-b", group: "space", value: "var(--ocelle-loop-a)", ref: ["loop-a"] },
      ),
    problems: ["token loop-a: reference cycle loop-a -> loop-b -> loop-a", "token loop-b: reference cycle loop-b -> loop-a -> loop-b"],
  },
  {
    rule: "for a duplicate name, taking the references of the first record of the name (no cycle through the second)",
    records: withAdded({ name: "loop-a", group: "space", value: "1px" }, { name: "loop-a", group: "space", value: "var(--ocelle-loop-a)", ref: ["loop-a"] }),
    problems: ["token loop-a: duplicate name"],
  },
  {
    rule: "for a colour value that is not a 6-digit hex",
    records: withRecord("color-ink", ink({ light: "#FFF", dark: "red" })),
    problems: ["token color-ink: light value #FFF is not a 6-digit hex colour or one colour token reference", "token color-ink: dark value red is not a 6-digit hex colour or one colour token reference"],
  },
  {
    rule: "for rgb(… / α) on a colour other than color-overlay",
    records: withRecord("color-ground", { name: "color-ground", group: "colour", value: { light: "rgb(0 0 0 / 0.5)", dark: "#000000" } }),
    problems: ["token color-ground: light value rgb(0 0 0 / 0.5) is not a 6-digit hex colour or one colour token reference"],
  },
  {
    rule: "for a color-overlay value that is neither rgb(… / α) nor a hex nor a reference",
    records: withRecord("color-overlay", { name: "color-overlay", group: "colour", value: { light: "rgb(0 0 0 / 0.5)", dark: "black" } }),
    problems: ["token color-overlay: dark value black is not a 6-digit hex colour, rgb(… / α) or one colour token reference"],
  },
  {
    rule: "for a colour value with more than one reference",
    records: withRecord(
        "color-focus",
        focus("var(--ocelle-color-ink) var(--ocelle-color-ground)", "var(--ocelle-color-ink)", { light: ["color-ink", "color-ground"], dark: ["color-ink"] }),
      ),
    problems: ["token color-focus: light value var(--ocelle-color-ink) var(--ocelle-color-ground) is not a 6-digit hex colour or one colour token reference"],
  },
  {
    rule: "for a colour reference to color-scheme or to a token outside the colour group",
    records: withRecord("color-focus", focus("var(--ocelle-color-scheme)", "var(--ocelle-space-4)", { light: ["color-scheme"], dark: ["space-4"] })),
    problems: ["token color-focus: light value references color-scheme, which is not a colour", "token color-focus: dark value references space-4, which is not a colour"],
  },
  {
    rule: "for a color-scheme value other than light and dark",
    records: withRecord("color-scheme", { name: "color-scheme", group: "colour", value: { light: "dark", dark: "dark" } }),
    problems: ["token color-scheme: value must be light in light and dark in dark"],
  },
  {
    rule: "for a color-scheme value that is right in light and wrong in dark",
    records: withRecord("color-scheme", { name: "color-scheme", group: "colour", value: { light: "light", dark: "light" } }),
    problems: ["token color-scheme: value must be light in light and dark in dark"],
  },
  {
    rule: "for contrast on a colour, and a ground, that are opaque in one theme only",
    records: withAdded(
        {
          name: "color-veil",
          group: "colour",
          value: { light: "#123456", dark: "var(--ocelle-color-overlay)" },
          ref: { light: [], dark: ["color-overlay"] },
          contrast: { kind: "text", grounds: ["color-ground"] },
        },
        {
          name: "color-sheet",
          group: "colour",
          value: { light: "var(--ocelle-color-overlay)", dark: "#000000" },
          ref: { light: ["color-overlay"], dark: [] },
        },
        { name: "color-mark", group: "colour", value: { light: "#123456", dark: "#654321" }, contrast: { kind: "non-text", grounds: ["color-sheet"] } },
      ),
    problems: ["token color-veil: contrast on a colour that is not opaque in both themes", "token color-mark: ground color-sheet is not opaque in both themes"],
  },
  {
    rule: "for contrast on a colour whose resolved value is not opaque",
    records: withAdded({
        name: "color-veil",
        group: "colour",
        value: { light: "var(--ocelle-color-overlay)", dark: "var(--ocelle-color-overlay)" },
        ref: { light: ["color-overlay"], dark: ["color-overlay"] },
        contrast: { kind: "text", grounds: ["color-ground"] },
      }),
    problems: ["token color-veil: contrast on a colour that is not opaque in both themes"],
  },
  {
    rule: "for a ground that is not opaque, directly or through a reference",
    records: withAdded(
        {
          name: "color-veil",
          group: "colour",
          value: { light: "var(--ocelle-color-overlay)", dark: "var(--ocelle-color-overlay)" },
          ref: { light: ["color-overlay"], dark: ["color-overlay"] },
        },
        { name: "color-mark", group: "colour", value: { light: "#123456", dark: "#654321" }, contrast: { kind: "non-text", grounds: ["color-overlay", "color-veil"] } },
      ),
    problems: ["token color-mark: ground color-overlay is not opaque in both themes", "token color-mark: ground color-veil is not opaque in both themes"],
  },
  {
    rule: "for contrast on a token outside the colour group",
    records: withRecord("space-4", { name: "space-4", group: "space", value: "1rem", contrast: { kind: "text", grounds: ["color-ground"] } }),
    problems: ["token space-4: contrast on a token outside the colour group"],
  },
  {
    rule: "for a theme-independent token with a light and a dark value",
    records: withRecord("space-4", { name: "space-4", group: "space", value: { light: "1rem", dark: "2rem" } }),
    problems: ["token space-4: group space is theme-independent but the value is per theme"],
  },
  {
    rule: "for a theme-dependent token with one value",
    records: withRecord("color-ink", ink("#111111")),
    problems: ["token color-ink: group colour is theme-dependent but the value is not per theme"],
  },
  {
    rule: "for exempt on a colour token other than color-disabled-ink",
    records: withRecord("color-ink", ink({ light: "#111111", dark: "#EEEEEE" }, { contrast: { kind: "text", grounds: ["color-ground"], exempt: true } })),
    problems: ["token color-ink: exempt is allowed only on color-disabled-ink"],
  },
  {
    rule: "for several rules at once, in source order",
    records: withAdded(ink({ light: "#111111", dark: "#EEEEEE" }), { name: "radius-3", group: "shape", value: "8px" }),
    problems: ["token color-ink: duplicate name", "token radius-3: excluded token (spec Appendix A.6)"],
  },
];

describe("validateSource() names the token and the rule", () => {
  it.each(cases)("$rule", ({ records, problems }) => {
    expect(() => {
      validateSource(records);
    }).toThrow(new Error(`invalid token source: ${problems.join("; ")}`));
  });

  it.each(["color-proto", "color-proto-bg", "font-size-ui", "font-size-body", "font-size-title", "radius-3"])("for the A.6 name %s", (name) => {
    expect(() => {
      validateSource(withAdded({ name, group: "type", value: "1rem" }));
    }).toThrow(new Error(`invalid token source: token ${name}: excluded token (spec Appendix A.6)`));
  });
});

describe("validateSource() allows exempt only on color-disabled-ink", () => {
  it("over the real source, for exempt on color-ink-muted by an override", () => {
    const muted = source.find((record) => record.name === "color-ink-muted");
    expect(muted?.contrast?.kind).toBe("text");
    const grounds = muted?.contrast?.grounds ?? [];
    expect(grounds).not.toHaveLength(0);
    const exempted = applyOverrides(source, [{ token: "color-ink-muted", contrast: { kind: "text", grounds, exempt: true } }]);
    expect(() => {
      validateSource(exempted);
    }).toThrow(new Error("invalid token source: token color-ink-muted: exempt is allowed only on color-disabled-ink"));
  });

  it("keeps the real source's exempt on color-disabled-ink", () => {
    expect(source.find((record) => record.name === "color-disabled-ink")?.contrast?.exempt).toBe(true);
    expect(() => {
      validateSource(source);
    }).not.toThrow();
  });
});

