  it("reads a hunk without a count as one line, skips pure deletions, and takes paths from file headers only", () => {
    const diff = [
      "diff --git a/gates/bin/x.ts b/gates/bin/x.ts",
      "index 1111111..2222222 100644",
      "--- a/gates/bin/x.ts",
      "+++ b/gates/bin/x.ts",
