describe("monospaceFamilies", () => {
  it("lists FR-022's monospace families, which the Storybook run-time check also uses", () => {
    expect([...monospaceFamilies].sort()).toEqual(
      [
        "monospace",
        "ui-monospace",
        "Menlo",
        "Monaco",
        "Consolas",
        "Courier",
        "Courier New",
        "SF Mono",
        "SFMono-Regular",
        "Liberation Mono",
        "DejaVu Sans Mono",
        "Lucida Console",
        "Roboto Mono",
        "Source Code Pro",
        "Fira Code",
        "Fira Mono",
        "JetBrains Mono",
        "Cascadia Code",
        "Cascadia Mono",
      ].sort(),
    );
  });

  it("are the families scanText reports in a font declaration", () => {
