import { describe, expect, it } from "vitest";
import { mutation } from "../bin/mutation.ts";
import { formatRecord, scanRecords } from "../lib/mutation/records.ts";
import { base, capture, context, fakeGit, fakeRepo, fakeStryker } from "./mutation-fakes.ts";

// Equivalent-mutant records (FR-012, data-model.md): a reasoned next-line record in changed code is listed with its
// path, line, mutator and reason; a record without a reason and every other disable form in a changed file is a
// finding (rule disable-form).
const path = "gates/lib/a.ts";
const noReason = "equivalent-mutant record without a reason; write the reason after the colon (FR-012)";
const otherForm = "only a reasoned next-line record directly above the mutated line may disable mutants (FR-012)";

const recorded = [
  "export async function f(a: number): Promise<number> {",
  "  // Stryker disable next-line ConditionalExpression: the guard only narrows the type",
  "  if (a > 0) return a;",
  "  // Stryker disable next-line StringLiteral, EqualityOperator:   both are logged only  ",
  '  log(a === 1 ? "one" : "");',
  "  // Stryker disable next-line all: process boundary, covered by gates-integration",
  "  if (import.meta.main) await main(run);",
  "  return 0;",
  "}",
].join("\n");

function file(ranges: readonly { start: number; end: number }[]) {
  return { path, ranges, lines: ranges.reduce((sum, r) => sum + r.end - r.start + 1, 0) };
}

describe("scanRecords", () => {
  it("lists the reasoned next-line records whose own line or mutated line changed", () => {
    expect(scanRecords(file([{ start: 3, end: 5 }]), recorded)).toEqual({
      records: [
        { path, line: 2, mutator: "ConditionalExpression", reason: "the guard only narrows the type" },
        { path, line: 4, mutator: "StringLiteral, EqualityOperator", reason: "both are logged only" },
      ],
      findings: [],
    });
  });

  it("lists a record whose own line changed even when its mutated line did not", () => {
    expect(scanRecords(file([{ start: 6, end: 6 }]), recorded)).toEqual({
      records: [
        { path, line: 6, mutator: "all", reason: "process boundary, covered by gates-integration" },
      ],
      findings: [],
    });
  });

  it("does not list a record when neither its own line nor its mutated line changed, at both edges", () => {
    // Changed lines 3 and 6: the record on line 2 (mutating line 3) and the record on line 6 are listed; the record
    // on line 4 (mutating line 5) lies between them, one line after line 3 and one line before line 6, and is not.
    expect(scanRecords(file([{ start: 3, end: 3 }, { start: 6, end: 6 }]), recorded)).toEqual({
      records: [
        { path, line: 2, mutator: "ConditionalExpression", reason: "the guard only narrows the type" },
        { path, line: 6, mutator: "all", reason: "process boundary, covered by gates-integration" },
      ],
      findings: [],
    });
  });

  it("makes a record without a reason and every other disable form in the changed file a finding", () => {
    const source = [
      "// Stryker disable next-line all",
      "x();",
      "// Stryker disable next-line all:   ",
      "y();",
      "// Stryker disable all",
      "z();",
      "// Stryker restore all",
      "/* Stryker disable next-line all: a block comment */",
      "w(); // Stryker disable next-line all: a trailing comment",
      "// Stryker disable StringLiteral: until restored",
      "//   Stryker   disable   next-line all: spaced so that Stryker does not read it as a record",
      "// A comment that mentions Stryker but disables nothing.",
      "v();",
    ].join("\n");
    const finding = (line: number, message: string): object => ({
      location: { path, line },
      gate: "mutation",
      rule: "disable-form",
      message,
    });
    expect(scanRecords(file([{ start: 13, end: 13 }]), source)).toEqual({
      records: [],
      findings: [
        finding(1, noReason),
        finding(3, noReason),
        finding(5, otherForm),
        finding(7, otherForm),
        finding(8, otherForm),
        finding(9, otherForm),
        finding(10, otherForm),
        finding(11, otherForm),
      ],
    });
  });
});

describe("scanRecords: the forms Stryker reads (added: mutation run)", () => {
  it("reads a record without a space after the slashes and trims the mutator list, as Stryker does", () => {
    const source = [
      "//Stryker disable next-line all: no space after the slashes",
      "x();",
      "// Stryker disable next-line StringLiteral : a space before the colon",
      "y();",
      "// Stryker disable next-line all; Stryker reads this as a record without a reason",
      "z();",
    ].join("\n");
    expect(scanRecords(file([{ start: 1, end: 6 }]), source)).toEqual({
      records: [
        { path, line: 1, mutator: "all", reason: "no space after the slashes" },
        { path, line: 3, mutator: "StringLiteral", reason: "a space before the colon" },
      ],
      findings: [{ location: { path, line: 5 }, gate: "mutation", rule: "disable-form", message: noReason }],
    });
  });
});

describe("formatRecord", () => {
  it("writes <path>:<line>: mutation: record: <mutator>: <reason> (data-model.md § Finding)", () => {
    expect(formatRecord({ path, line: 2, mutator: "ConditionalExpression", reason: "the guard only narrows the type" })).toBe(
      "gates/lib/a.ts:2: mutation: record: ConditionalExpression: the guard only narrows the type",
    );
  });
});

describe("mutation gate: records and disable forms (US2 scenario 4)", () => {
  const diff = [
    `diff --git a/${path} b/${path}`,
    "index 1111111..2222222 100644",
    `--- a/${path}`,
    `+++ b/${path}`,
    "@@ -3,3 +3,3 @@ export async function f(a: number): Promise<number> {",
    "-old",
    "+new",
    "",
  ].join("\n");

  it("passes with every mutant killed and lists the records for the review", async () => {
    const { io, out, err } = capture();
    const tools = { git: fakeGit(diff), ...fakeRepo({ [path]: recorded }, fakeStryker(() => "Killed")) };
    const code = await mutation(context(["--base", base]), tools, io);
    expect({ code, out, err }).toEqual({
      code: 0,
      out: [
        "gates/lib/a.ts:2: mutation: record: ConditionalExpression: the guard only narrows the type",
        "gates/lib/a.ts:4: mutation: record: StringLiteral, EqualityOperator: both are logged only",
        "mutation: 1 mutant on the changed lines of 1 file, none survived; 0 timeouts, 0 compile errors, 0 zero-mutant entries; 2 equivalent records",
      ],
      err: [],
    });
  });

  it("fails on a disable form in a changed file even when every mutant is killed", async () => {
    const source = recorded.replace("// Stryker disable next-line all: process boundary", "// Stryker disable all: process boundary");
    const { io, out, err } = capture();
    const tools = { git: fakeGit(diff), ...fakeRepo({ [path]: source }, fakeStryker(() => "Killed")) };
    const code = await mutation(context(["--base", base]), tools, io);
    expect({ code, out, err }).toEqual({
      code: 1,
      out: [
        "gates/lib/a.ts:2: mutation: record: ConditionalExpression: the guard only narrows the type",
        "gates/lib/a.ts:4: mutation: record: StringLiteral, EqualityOperator: both are logged only",
        `gates/lib/a.ts:6: mutation: disable-form: ${otherForm}`,
        "mutation: 1 finding in 1 changed file (1 mutant on changed lines; 0 timeouts, 0 compile errors, 0 zero-mutant entries)",
      ],
      err: [],
    });
  });

  it("exits 2 when a changed file cannot be read", async () => {
    const { io, out, err } = capture();
    const tools = { git: fakeGit(diff), ...fakeRepo({}, fakeStryker(() => "Killed")) };
    const code = await mutation(context(["--base", base]), tools, io);
    expect({ code, out, err }).toEqual({
      code: 2,
      out: [],
      err: [`mutation: could not run: cannot read ${path}; check out the files of the change`],
    });
  });
});

gates/test/prefix-parts.test.ts.source:
import { describe, expect, it } from "vitest";
import { checkPackages, scanText, selectCovered } from "../bin/prefix.ts";

// The prefix gate at the edges (FR-022, research.md R-12; phase 4 review round 1, R1-08 and R1-09): spaces before the
// colon of a font declaration, the monospace message with each family once, the summary's file count, and the
// selection of the package files the gate reads.
const bytes = (text: string): Uint8Array => new TextEncoder().encode(text);

describe("scanText: font declarations", () => {
  it.each(["font-family : monospace;", "font\t:\tmonospace;", "font-family  :  Menlo, monospace;"])("finds a monospace family with spaces before the colon: %s", (text) => {
    expect(scanText("packages/a/src/x.css", text).map((found) => found.rule)).toEqual(["monospace"]);
  });

  it("names each monospace family of a line once, in order, in the message", () => {
    expect(scanText("packages/a/src/x.css", "a { font-family: Menlo, monospace; } b { font: 12px Menlo; }")).toEqual([
      {
        location: { path: "packages/a/src/x.css", line: 1 },
        gate: "prefix",
        rule: "monospace",
        message: "monospace font family Menlo, monospace in a font declaration (FR-022)",
      },
    ]);
  });
});

describe("checkPackages: the summary", () => {
  it("counts the files with findings, not the findings or the files checked", () => {
    const files = [
      { path: "packages/a/src/x.ts", bytes: bytes("sk-a\nsk-b\n") },
      { path: "packages/a/src/y.ts", bytes: bytes("ok\n") },
      { path: "packages/a/src/z.css", bytes: bytes("a { font-family: monospace; }\n") },
    ];
    const result = checkPackages(files);
    expect({ exit: result.exit, summary: "summary" in result ? result.summary : undefined }).toEqual({ exit: 1, summary: "prefix: 3 findings in 2 files" });
  });
});

describe("selectCovered", () => {
  it("keeps the covered package files only, sorted", () => {
    const paths = ["packages/b/src/z.ts", "packages/a/README.md", "packages/a/dist/x.js", "packages/a/node_modules/x/y.js", "gates/x.ts", "packages/a/src/a.css"];
    expect(selectCovered(paths)).toEqual(["packages/a/dist/x.js", "packages/a/src/a.css", "packages/b/src/z.ts"]);
  });
});

